      for (let j = 15; j >= 12; j--) { C[j] = (C[j] + 1) & 0xff; if (C[j]) break; }
      const ks = enc(w, C); for (let j = 0; j < 16 && o + j < ct.length; j++) out[o + j] = ct[o + j] ^ ks[j];
