  function b64d(s) { s = s.replace(/[^A-Za-z0-9+/]/g, ''); const o = new Uint8Array((s.length * 3) >> 2); let b = 0, n = 0, p = 0;
    for (const ch of s) { b = (b << 6) | B64.indexOf(ch); n += 6; if (n >= 8) { n -= 8; o[p++] = (b >> n) & 0xff; } } return o.subarray(0, p); }
